// Load tenant context and workflow execution ID
const tenantId = $env.TENANT_ID;
const clientLabel = $env.CLIENT_LABEL;
const useSampleData = $env.USE_SAMPLE_DATA === 'true';
const workflowExecutionId = $executionId;

return {
  tenant_id: tenantId,
  client_label: clientLabel,
  use_sample_data: useSampleData,
  workflow_execution_id: workflowExecutionId,
  run_started_at: new Date().toISOString()
};

// Normalize invoice data and compute days_overdue
const items = $input.all();
const context = items[0].json; // First item has context
const defaultTz = $env.DEFAULT_TIMEZONE || 'America/Los_Angeles';

const normalized = [];

for (const item of items.slice(1)) { // Skip context item
  const invoice = item.json;

  // Convert amounts to cents (integer)
  const amountTotalCents = Math.round((invoice.amount_total || 0) * 100);
  const amountDueCents = Math.round((invoice.amount_due || invoice.amount_total || 0) * 100);

  // Compute days_overdue
  const dueDate = new Date(invoice.due_date);
  const now = new Date();
  const daysOverdue = Math.floor((now - dueDate) / (1000 * 60 * 60 * 24));

  // Skip if not actually overdue
  if (daysOverdue < 1) {
    console.log(`Skipping ${invoice.invoice_id}: not overdue (${daysOverdue} days)`);
    continue;
  }

  normalized.push({
    tenant_id: context.tenant_id,
    invoice_id: invoice.invoice_id,
    invoice_number: invoice.invoice_number,
    customer_id: invoice.customer_id,
    customer_name: invoice.customer_name,
    customer_email: invoice.customer_email || null,
    customer_phone: invoice.customer_phone || null,
    currency: invoice.currency || 'USD',
    amount_total_cents: amountTotalCents,
    amount_due_cents: amountDueCents,
    due_date: invoice.due_date,
    status: invoice.status,
    payment_link: invoice.payment_link || null,
    days_overdue: daysOverdue
  });
}

return normalized.map(inv => ({ json: inv }));

// Aggregate run summary
const items = $input.all();

const summary = {
  run_id: items[0].json.workflow_execution_id,
  tenant_id: items[0].json.tenant_id,
  invoices_processed: items.length,
  enqueued_count: items.filter(i => i.json.status === 'queued').length,
  completed_at: new Date().toISOString()
};

console.log('Producer run summary:', JSON.stringify(summary, null, 2));

return [{ json: summary }];
